<section class="card"><h3>Return Outcomes</h3><p>Lifecycle status and inspection condition are separate. Each physical unit or quantity group keeps its own recorded outcome.</p><div class="table-wrapper"><table class="request-table"><thead><tr><th>Resource / Unit</th><th>Reported condition</th><th>Inspected condition</th><th>Physically returned</th><th>Lost quantity</th><th>Inspection remarks</th></tr></thead><tbody>
<?php foreach($returnDetails as $detail):?><tr><td><?php echo htmlspecialchars($detail['resource_name'].($detail['asset_tag']?' | '.$detail['asset_tag']:''));?></td><td><?php echo htmlspecialchars((string)$detail['reported_condition']);?></td><td><?php echo htmlspecialchars((string)($detail['inspection_condition']??'Pending inspection'));?></td><td><?php echo (int)$detail['returned_quantity'];?></td><td><?php echo (int)$detail['lost_quantity'];?></td><td><?php echo htmlspecialchars((string)$detail['inspection_remarks']);?></td></tr><?php endforeach;?></tbody></table></div></section>
